// reserved stock server-side.
const abandonOrders = async () => {
  await fetch('/api/orders/razorpay/abandon', {
    method: 'POST',
    credentials: 'same-origin',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ orderIds: result.orderIds }),
