import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getRiderSessionFromRequest } from '@/lib/rider-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type DeliveryStatus = 'unassigned' | 'assigned' | 'picked_up' | 'out_for_delivery' | 'delivered'

type OrderRow = {
  id: string
  farmer_id: string
  produce_name: string | null
  quantity: number | null
  unit: string | null
  total_price: number | null
  buyer_name: string | null
  buyer_phone: string | null
  payment_method: string | null
  payment_status: string | null
  delivery_status: DeliveryStatus | null
  // Cash the rider must take at the door on a part-paid COD order.
  cod_balance_due: number | null
  delivery_address: string | null
  delivery_city: string | null
  delivery_landmark: string | null
  delivery_pincode: string | null
  delivery_alt_phone: string | null
  delivery_boy_id: string | null
  delivery_fee: number | null
  rider_payout: number | null
  assigned_at: string | null
  picked_up_at: string | null
  out_for_delivery_at: string | null
  delivered_at: string | null
  created_at: string
}

type Farmer = { id: string; name: string; village: string; phone: string | null; farm_address: string | null }

export async function GET(req: NextRequest) {
  const session = getRiderSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Not logged in.' }, { status: 401 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Gate: only active riders see orders. Suspended/pending accounts are kicked
  // out of /api/rider/me as well, but we double-check here to be safe.
  const { data: rider } = await supabase
    .from('delivery_boys')
    .select('id, status, service_pincodes')
    .eq('id', session.riderId)
    .maybeSingle() as { data: { id: string; status: string; service_pincodes: string[] | null } | null }

  if (!rider || rider.status !== 'active') {
    return NextResponse.json({ error: 'Account not active.' }, { status: 403 })
  }

  // Available — farmer-approved home deliveries that no rider has taken yet.
  // Mine — anything currently assigned to me and not yet delivered.
  //
  // Availability is scoped to the rider's declared pincodes. A rider with none
  // on file covers nothing and sees nothing: showing them every order on the
  // platform (the old fallback) is how a rider in one district ends up looking
  // at deliveries in another. /api/rider/orders/[id]/accept enforces the same
  // rule, so this filter isn't the only thing standing between them.
  const ridersPincodes = (rider.service_pincodes ?? []).filter((p) => /^\d{6}$/.test(p))

  // No pincodes on file → nothing is offered. Deliveries the rider already
  // accepted still load below: taking their service area away must not strand
  // a buyer whose food is already on a bike.
  let availableRaw: OrderRow[] | null = []
  if (ridersPincodes.length > 0) {
    const { data, error: availErr } = await supabase
      .from('orders')
      .select(
        'id, farmer_id, produce_name, quantity, unit, total_price, payment_method, payment_status, delivery_pincode, delivery_status, delivery_fee, rider_payout, created_at',
      )
      .eq('delivery_type', 'home_delivery')
      .eq('status', 'approved')
      .is('delivery_boy_id', null)
      .or('delivery_status.is.null,delivery_status.eq.unassigned')
      .in('delivery_pincode', ridersPincodes)
      .order('created_at', { ascending: true })
      .limit(50) as { data: OrderRow[] | null; error: { message: string } | null }

    if (availErr) {
      console.error('[YFF rider/orders] available query failed:', availErr.message)
      return NextResponse.json({ error: 'Could not load orders.' }, { status: 500 })
    }
    availableRaw = data
  }

  const { data: mineRaw, error: mineErr } = await supabase
    .from('orders')
    .select(
      'id, farmer_id, produce_name, quantity, unit, total_price, buyer_name, buyer_phone, payment_method, payment_status, cod_balance_due, delivery_status, delivery_address, delivery_city, delivery_landmark, delivery_pincode, delivery_alt_phone, delivery_boy_id, delivery_fee, rider_payout, assigned_at, picked_up_at, out_for_delivery_at, delivered_at, created_at',
    )
    .eq('delivery_boy_id', session.riderId)
    .in('delivery_status', ['assigned', 'picked_up', 'out_for_delivery'])
    .order('assigned_at', { ascending: true })
    .limit(50) as { data: OrderRow[] | null; error: { message: string } | null }

  if (mineErr) {
    console.error('[YFF rider/orders] mine query failed:', mineErr.message)
    return NextResponse.json({ error: 'Could not load your deliveries.' }, { status: 500 })
  }

  // Past deliveries this rider has finished. Most recent first.
  const { data: historyRaw, error: historyErr } = await supabase
    .from('orders')
    .select(
      'id, farmer_id, produce_name, quantity, unit, total_price, buyer_name, payment_method, delivery_status, delivery_pincode, delivery_fee, rider_payout, delivered_at, created_at',
    )
    .eq('delivery_boy_id', session.riderId)
    .eq('delivery_status', 'delivered')
    .order('delivered_at', { ascending: false })
    .limit(100) as { data: OrderRow[] | null; error: { message: string } | null }

  if (historyErr) {
    console.error('[YFF rider/orders] history query failed:', historyErr.message)
    return NextResponse.json({ error: 'Could not load your delivery history.' }, { status: 500 })
  }

  const farmerIds = [...new Set([
    ...(availableRaw ?? []).map((o) => o.farmer_id),
    ...(mineRaw ?? []).map((o) => o.farmer_id),
    ...(historyRaw ?? []).map((o) => o.farmer_id),
  ].filter(Boolean))]

  let farmerMap: Record<string, Farmer> = {}
  if (farmerIds.length > 0) {
    let farmersData: Array<{ id: string; name: string; village: string; phone: string | null; farm_address?: string | null }> | null = null
    const withAddress = await supabase
      .from('farmers')
      .select('id, name, village, phone, farm_address')
      .in('id', farmerIds)
    if (withAddress.error) {
      // farm_address column not migrated yet — fall back so the rider still
      // sees orders, just without the pickup address.
      console.warn('[YFF rider/orders] farm_address select failed, falling back:', withAddress.error.message)
      const fallback = await supabase
        .from('farmers')
        .select('id, name, village, phone')
        .in('id', farmerIds)
      farmersData = fallback.data ?? null
    } else {
      farmersData = withAddress.data ?? null
    }
    farmerMap = Object.fromEntries(
      (farmersData ?? []).map((f) => [f.id, {
        id: f.id,
        name: f.name,
        village: f.village,
        phone: f.phone ?? null,
        farm_address: f.farm_address ?? null,
      }]),
    )
  }

  // Available rows are public to all active riders — withhold consumer name,
  // phone, and street so a rider can't fish for personal info by browsing.
  const available = (availableRaw ?? []).map((o) => {
    const farmer = farmerMap[o.farmer_id] ?? null
    return {
      id: o.id,
      produce_name: o.produce_name,
      quantity: o.quantity,
      unit: o.unit,
      total_price: o.total_price,
      payment_method: o.payment_method,
      payment_status: o.payment_status,
      delivery_pincode: o.delivery_pincode,
      delivery_fee: o.delivery_fee ?? 0,
      rider_payout: o.rider_payout ?? 0,
      created_at: o.created_at,
      farmer: farmer
        ? { name: farmer.name, village: farmer.village, farm_address: farmer.farm_address }
        : null,
    }
  })

  const mine = (mineRaw ?? []).map((o) => ({
    ...o,
    farmer: farmerMap[o.farmer_id] ?? null,
  }))

  const history = (historyRaw ?? []).map((o) => {
    const farmer = farmerMap[o.farmer_id] ?? null
    return {
      id: o.id,
      produce_name: o.produce_name,
      quantity: o.quantity,
      unit: o.unit,
      total_price: o.total_price,
      buyer_name: o.buyer_name,
      payment_method: o.payment_method,
      delivery_pincode: o.delivery_pincode,
      delivery_fee: o.delivery_fee ?? 0,
      rider_payout: o.rider_payout ?? 0,
      delivered_at: o.delivered_at,
      created_at: o.created_at,
      farmer: farmer ? { name: farmer.name, village: farmer.village } : null,
    }
  })

  const totalEarned = history.reduce((s, o) => s + (o.rider_payout ?? 0), 0)

  return NextResponse.json({
    available,
    mine,
    history,
    totalEarned,
    notice: ridersPincodes.length === 0
      ? 'No service area on file. Ask the moderator to set the pincodes you cover.'
      : null,
  })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getRiderSessionFromRequest } from '@/lib/rider-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  if (!UUID_RE.test(id)) return NextResponse.json({ error: 'Invalid order id.' }, { status: 400 })

  const session = getRiderSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Not logged in.' }, { status: 401 })

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  const { data: rider } = await supabase
    .from('delivery_boys')
    .select('id, status, service_pincodes')
    .eq('id', session.riderId)
    .maybeSingle() as { data: { id: string; status: string; service_pincodes: string[] | null } | null }
  if (!rider || rider.status !== 'active') {
    return NextResponse.json({ error: 'Account not active.' }, { status: 403 })
  }

  // Coverage gate. The job list only *shows* orders in the rider's pincodes —
  // it doesn't stop anyone from POSTing an arbitrary order id, and accepting
  // reveals the buyer's name, phone and street. So re-check coverage here,
  // where it actually counts. A rider with no pincodes on file covers nothing.
  const covered = (rider.service_pincodes ?? []).filter((p) => /^\d{6}$/.test(p))
  if (covered.length === 0) {
    return NextResponse.json(
      { error: 'No service area on file. Ask the moderator to set your pincodes.' },
      { status: 403 },
    )
  }

  const { data: target } = await supabase
    .from('orders')
    .select('id, delivery_pincode')
    .eq('id', id)
    .maybeSingle() as { data: { id: string; delivery_pincode: string | null } | null }
  if (!target) return NextResponse.json({ error: 'Order not found.' }, { status: 404 })
  if (!target.delivery_pincode || !covered.includes(target.delivery_pincode)) {
    return NextResponse.json({ error: 'This delivery is outside your service area.' }, { status: 403 })
  }

  // Optimistic-lock claim — only succeeds if the order is still unclaimed and
  // home-delivery + approved. Two riders tapping Accept simultaneously can't
  // both win because the WHERE clause excludes any row that already has a
  // delivery_boy_id.
  const now = new Date().toISOString()
  const { data: claimed, error } = await supabase
    .from('orders')
    .update({
      delivery_boy_id: session.riderId,
      delivery_status: 'assigned',
      assigned_at: now,
    })
    .eq('id', id)
    .eq('delivery_type', 'home_delivery')
    .eq('status', 'approved')
    .is('delivery_boy_id', null)
    .select('id')

  if (error) {
    console.error('[YFF rider/accept] update failed:', error.message)
    return NextResponse.json({ error: 'Could not accept order.' }, { status: 500 })
  }
  if (!claimed || claimed.length === 0) {
    return NextResponse.json({ error: 'This order was already taken or is no longer available.' }, { status: 409 })
  }

  // Belt-and-braces: if delivery_status was 'unassigned' rather than NULL,
  // the .is() check above wouldn't have filtered it out. We additionally
  // refuse if a prior status was further along the pipeline. (The combination
  // of the IS NULL filter on delivery_boy_id + the status checks above already
  // makes this safe in practice.)

  return NextResponse.json({ ok: true })
}

// Delivery charge for a checkout.
//
// The charge is a single figure for the WHOLE checkout, even though a
// multi-farmer cart is placed as one order batch per farmer:
//
//     delivery = farmers === 0 ? 0 : base + extra × (farmers - 1)
//
// `base` covers the rider's trip (and the first farmer's pickup); every
// additional farmer is another pickup stop, so it adds `extra`. Both figures
// are moderator-set (platform_settings.delivery_base_fee / delivery_extra_fee)
// and default to ₹30 / ₹15. The resolved rupees are stamped on orders.delivery_fee
// at placement (see src/app/api/orders/place/route.ts): `base` on the first
// farmer's batch, `extra` on each subsequent farmer's batch, so the stamped
// fees across a checkout always sum to the formula above.
//
// Refunds (farmer decline / buyer cancel) recompute how many farmers remain in
// the checkout and give back the drop — see planDeliveryRefund below.

import type { SupabaseClient } from '@supabase/supabase-js'

// Sensible ceiling for the moderator inputs — a guard against a fat-fingered
// entry, not a business rule.
export const DELIVERY_FEE_MAX = 1000

// Launch defaults, also used as the fallback when the settings row/columns
// aren't migrated yet so checkout is never blocked.
export const DEFAULT_DELIVERY_BASE_FEE = 30
export const DEFAULT_DELIVERY_EXTRA_FEE = 15

export type DeliveryCharges = { base: number; extra: number }

// Total delivery charge for a checkout with `farmerCount` participating farmers.
export function computeDeliveryTotal(farmerCount: number, { base, extra }: DeliveryCharges): number {
  if (!Number.isFinite(farmerCount) || farmerCount <= 0) return 0
  const b = Math.max(0, Math.round(base))
  const e = Math.max(0, Math.round(extra))
  return b + e * (farmerCount - 1)
}

// Read the current base + extra charges. Best-effort: if the table/columns
// don't exist yet (migration not applied) or anything fails, fall back to the
// launch defaults so checkout and refunds are never blocked.
export async function getDeliveryCharges(supabase: SupabaseClient): Promise<DeliveryCharges> {
  try {
    const { data, error } = await supabase
      .from('platform_settings')
      .select('delivery_base_fee, delivery_extra_fee')
      .eq('id', 1)
      .maybeSingle()
    if (error) return { base: DEFAULT_DELIVERY_BASE_FEE, extra: DEFAULT_DELIVERY_EXTRA_FEE }
    const base = Number(data?.delivery_base_fee)
    const extra = Number(data?.delivery_extra_fee)
    return {
      base: Number.isFinite(base) && base >= 0 ? base : DEFAULT_DELIVERY_BASE_FEE,
      extra: Number.isFinite(extra) && extra >= 0 ? extra : DEFAULT_DELIVERY_EXTRA_FEE,
    }
  } catch {
    return { base: DEFAULT_DELIVERY_BASE_FEE, extra: DEFAULT_DELIVERY_EXTRA_FEE }
  }
}

// ── Refunds ──────────────────────────────────────────────────────────────
//
// planDeliveryRefund works out how much delivery charge to give back when one
// order in a checkout is declined/cancelled, and which orders' payments to pull
// it from. It is a pure function so the farmer-decline and buyer-cancel routes
// share exactly one implementation and can't drift.

// A status that means the order is no longer part of the delivery run.
const GONE = new Set(['declined', 'cancelled'])

// The minimum shape planDeliveryRefund needs from each sibling order row.
export type RefundOrderRow = {
  id: string
  farmer_id: string | null
  status: string | null
  delivery_fee: number | null
  delivery_fee_refunded: number | null
  payment_status: string | null
  razorpay_payment_id: string | null
}

// One refund to issue against one order's payment.
export type DeliveryRefundAllocation = {
  orderId: string
  // Rupees to refund from THIS order's captured payment.
  amount: number
  // How much of this row's delivery_fee will have been refunded after this
  // allocation (row.delivery_fee_refunded + amount) — write straight back.
  newRefundedTotal: number
  razorpayPaymentId: string | null
  // true → issue a real Razorpay refund; false → a non-Razorpay captured
  // payment, so the caller flags it for manual settlement instead.
  viaRazorpay: boolean
}

export type DeliveryRefundPlan = {
  // Total delivery rupees to refund across all allocations.
  owed: number
  allocations: DeliveryRefundAllocation[]
}

function participating(row: RefundOrderRow): boolean {
  return !GONE.has(String(row.status ?? ''))
}

// Was money actually captured for this row (so a delivery refund is possible)?
function captured(row: RefundOrderRow): { yes: boolean; viaRazorpay: boolean } {
  const s = String(row.payment_status ?? '')
  const viaRazorpay = (s === 'paid' || s === 'deposit_paid') && !!row.razorpay_payment_id
  const otherPaid = s === 'completed' || s === 'payment_claimed' || s === 'pending_confirmation'
  return { yes: viaRazorpay || otherPaid, viaRazorpay }
}

function refundableDelivery(row: RefundOrderRow): number {
  return Math.max(0, (Number(row.delivery_fee) || 0) - (Number(row.delivery_fee_refunded) || 0))
}

/**
 * Plan the delivery-charge refund for cancelling one order out of a checkout.
 *
 * @param siblings  every order row sharing the checkout_id (including the one
 *                  being cancelled), each still carrying its CURRENT status —
 *                  i.e. call this BEFORE writing the declined/cancelled status.
 * @param cancelId  the order id being declined/cancelled.
 * @param charges   the current base/extra (from getDeliveryCharges).
 *
 * Returns the rupees to give back and the per-order allocations. Item price and
 * platform fee are handled by the caller; this covers only delivery.
 */
export function planDeliveryRefund(
  siblings: RefundOrderRow[],
  cancelId: string,
  { base, extra }: DeliveryCharges,
): DeliveryRefundPlan {
  const target = siblings.find((r) => r.id === cancelId)
  if (!target) return { owed: 0, allocations: [] }

  // Farmers with at least one live order, before vs after this cancellation.
  const farmersOf = (rows: RefundOrderRow[]) =>
    new Set(rows.filter(participating).map((r) => String(r.farmer_id ?? '')))
  const before = farmersOf(siblings).size
  const after = farmersOf(siblings.filter((r) => r.id !== cancelId)).size

  // Delivery money still held (stamped but not yet refunded) across the whole
  // checkout — includes residual left on already-cancelled base rows.
  const remainingHeld = siblings.reduce((s, r) => s + refundableDelivery(r), 0)

  // How much the delivery charge drops.
  //   - farmer still has other live orders (before === after) → no drop (Case 5)
  //   - last farmer leaving → refund everything still held (base included)
  //   - a non-last farmer leaving → refund one `extra` unit
  let owed: number
  if (after === before) owed = 0
  else if (after === 0) owed = remainingHeld
  else owed = Math.min(Math.max(0, Math.round(extra)), remainingHeld)

  // Only rows whose payment was captured can actually be refunded; never plan
  // to give back more than was collected.
  const candidates = siblings
    .map((r) => ({ row: r, cap: captured(r), refundable: refundableDelivery(r) }))
    .filter((c) => c.cap.yes && c.refundable > 0)
    // Pull from the cancelled order first, then its siblings.
    .sort((a, b) => (a.row.id === cancelId ? -1 : b.row.id === cancelId ? 1 : 0))
  const allocatable = candidates.reduce((s, c) => s + c.refundable, 0)
  owed = Math.min(owed, allocatable)

  const allocations: DeliveryRefundAllocation[] = []
  let left = owed
  for (const c of candidates) {
    if (left <= 0) break
    const amount = Math.min(left, c.refundable)
    if (amount <= 0) continue
    allocations.push({
      orderId: c.row.id,
      amount,
      newRefundedTotal: (Number(c.row.delivery_fee_refunded) || 0) + amount,
      razorpayPaymentId: c.row.razorpay_payment_id,
      viaRazorpay: c.cap.viaRazorpay,
    })
    left -= amount
  }

  return { owed, allocations }
}

// Harvest-as-product: record which harvest each line sold. rows are built 1:1
// with items in loop order, so rows[i] matches items[i]. Only stamped when the
// cart actually references harvests — a legacy produce-only checkout never
// touches the column before its migration runs — and when it is, every row
// carries it (null where absent) so the bulk insert has a uniform column set.
if (harvestIds.length > 0) {
  items.forEach((it, i) => { if (rows[i]) rows[i].harvest_id = it.harvestId ?? null })
}

// Platform fee (moderator commission) — a % charged PER ITEM and stamped on
// each row (unlike delivery_fee, which is one-per-cart on the first row). Per
// row means a single-item cancel/decline withholds or refunds exactly that
// item's own fee, and the per-item fees the buyer sees at checkout sum to what
// we charge. Resolved server-side; 0 unless the moderator set a fee. Only
// touched when a fee applies, so the column is never referenced before its
// migration runs — and when it is, every row in the batch carries it (even 0)
// so the bulk insert has a uniform column set.
const feePercent = await getPlatformFeePercent(supabase)
let platformFee = 0
if (feePercent > 0) {
  for (const r of rows) {
    const fee = computePlatformFee(Number(r.total_price) || 0, feePercent)
    r.platform_fee = fee
    platformFee += fee
  }
}

// Part-paid COD — the buyer prepays a deposit online and owes the rest in
// cash at handover. Stamped per row for the same reason as platform_fee: a
// single-line cancel then forfeits (or a decline refunds) exactly that
// line's own deposit. /api/orders/razorpay/create charges the sum of these
// rather than the full total, and the rider collects cod_balance_due at the
// door. depositPercent is 0 until the migration runs, which leaves COD
// behaving exactly as it does today.
let codDeposit = 0
if (paymentMethod === 'cod') {
  const depositPercent = await getCodDepositPercent(supabase)
  if (depositPercent > 0) {
    for (const r of rows) {
      const split = computeCodSplit(
        Number(r.total_price) || 0,
        Number(r.platform_fee) || 0,
        Number(r.delivery_fee) || 0,
        depositPercent,
      )
      r.cod_deposit = split.deposit
      r.cod_balance_due = split.balanceDue
      codDeposit += split.deposit
    }
  }
}

// Atomic stock claim. decrement_stock returns false if the listing went
// below zero (or vanished). On any failure we revert prior claims so we
// don't leak inventory.
// A claim is against a harvest (harvest-as-product) or, for legacy produce-
// card lines, the listing itself. We revert with the matching increment RPC.
const claimed: Array<{ harvestId?: string; listingId: string; qty: number }> = []
const revertClaims = async () => {
  for (const c of claimed) {
    try {
      if (c.harvestId) {
        await supabase.rpc('increment_harvest_stock', { p_harvest_id: c.harvestId, p_qty: c.qty })
      } else {
        await supabase.rpc('increment_stock', { p_listing_id: c.listingId, p_qty: c.qty })
      }
    } catch (e) {
      console.error('[YFF] stock revert failed:', e)
    }

    consumer_id: buyerId,
    idempotency_key: idempotencyKey,
    pickup_location: rowDeliveryType === 'self_pickup' && typeof pickupLocation === 'string'
      ? pickupLocation.slice(0, 200)
      : null,
    status: 'pending',
    payment_method: paymentMethod,
    payment_status: 'pending',
    delivery_type: rowDeliveryType,
    delivery_status: rowDeliveryType === 'home_delivery' ? 'unassigned' : null,
    delivery_address: rowShips ? deliveryAddress : (isGuest ? deliveryAddress : null),
    delivery_city: rowShips ? deliveryCity : null,
    delivery_landmark: rowShips ? deliveryLandmark : null,
    delivery_pincode: rowShips ? deliveryPincode : null,
    delivery_alt_phone: rowShips ? deliveryAltPhone : null,
    handover_otp: sharedHandoverOtp,
    // Links this row to the other farmers' batches of the same checkout, so
    // decline/cancel can count the remaining farmers and refund the delivery
    // drop. NULL for single-farmer legacy checkouts.
    checkout_id: checkoutId,
    // This farmer's delivery share is stamped on one row below (0 elsewhere).
    // sum(delivery_fee) over a batch === this farmer's share of the charge.
    delivery_fee: 0,
    delivery_fee_refunded: 0,
    rider_payout: 0,
  })
}

if (deliveryFee > 0) {
  // Stamp this farmer's delivery share on one row. Prefer a home-delivery row
  // (the rider earns it as rider_payout); but with "every farmer counts",
  // a pickup-only farmer in a delivery checkout still owes `extra`, so fall
  // back to the first row — with no rider_payout, since no rider serves it.
  const deliveryRow = rows.find((r) => r.delivery_type === 'home_delivery')
  const feeRow = deliveryRow ?? rows[0]
  if (feeRow) {
    feeRow.delivery_fee = deliveryFee
    feeRow.rider_payout = deliveryRow ? deliveryFee : 0
  }
}

